package br.com.admeclesial.domain.matrimonio;
import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial; import br.com.admeclesial.domain.pessoa.Pessoa; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="celebracao_matrimonial",schema="adm_eclesial") public class CelebracaoMatrimonial { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="processo_matrimonial_id",unique=true) ProcessoMatrimonial processo; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="organizacao_eclesial_id") OrganizacaoEclesial organizacao; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="celebrante_pessoa_id") Pessoa celebrante; @Column(name="data_celebracao",nullable=false) LocalDate dataCelebracao; @Column(length=200) String local; @Column(columnDefinition="text") String observacao; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public ProcessoMatrimonial getProcesso(){return processo;} public OrganizacaoEclesial getOrganizacao(){return organizacao;} public Pessoa getCelebrante(){return celebrante;} public LocalDate getDataCelebracao(){return dataCelebracao;} public String getLocal(){return local;} public String getObservacao(){return observacao;} public void setProcesso(ProcessoMatrimonial v){processo=v;} public void setOrganizacao(OrganizacaoEclesial v){organizacao=v;} public void setCelebrante(Pessoa v){celebrante=v;} public void setDataCelebracao(LocalDate v){dataCelebracao=v;} public void setLocal(String v){local=v;} public void setObservacao(String v){observacao=v;} }